<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['admin','superadmin']);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$recipient=(int)$_POST['recipient_id'];$type=$_POST['type'];$message=trim($_POST['message']);if($recipient && $message!==''){notify_user($pdo,$recipient,$type,$message,!empty($_POST['item_id'])?(int)$_POST['item_id']:null);$msg='Notification sent.';}}
$users=$pdo->query("SELECT id,full_name,username FROM accounts WHERE role='user' AND account_status='active' ORDER BY full_name")->fetchAll();$rows=$pdo->query("SELECT n.*,a.full_name AS recipient FROM notifications n LEFT JOIN accounts a ON a.id=n.recipient_id ORDER BY n.created_at DESC LIMIT 100")->fetchAll();page_header('Admin Notifications');?><h1>Send a Notification</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><div class="panel-body"><form method="post"><?=csrf_field()?><div class="field"><label>Recipient</label><select name="recipient_id" required><option value="">Choose user</option><?php foreach($users as $x):?><option value="<?=$x['id']?>"><?=e($x['full_name'])?> (<?=e($x['username'])?>)</option><?php endforeach;?></select></div><div class="field"><label>Type</label><select name="type"><?php foreach(['Please visit the Lost and Found Office','Item recovered and ready for claiming','Item status updated','General'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></div><div class="field"><label>Related Item ID (optional)</label><input type="number" name="item_id"></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><button>Send Notification</button></form></div></div><h2>Recent Notifications</h2><div class="table-wrap"><table><tr><th>Recipient</th><th>Type</th><th>Message</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['recipient']??'Deleted account')?></td><td><?=e($r['notification_type'])?></td><td><?=e($r['message'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php page_footer();?>
